import { StrictMode, Component, Suspense, lazy } from 'react'
import { createRoot } from 'react-dom/client'
import { AppProviders } from './app/AppProviders'
import './index.css'
import App from './App'
import { isUiLabHostAllowed } from './lib/uiLabAccess'

const demoRequested = new URLSearchParams(window.location.search).get('demo') === '1'

if (demoRequested) {
  const manifestLink = document.querySelector('link[rel="manifest"]')
  manifestLink?.setAttribute('href', '/manifest-demo.json')

  document
    .querySelector('meta[name="apple-mobile-web-app-title"]')
    ?.setAttribute('content', 'Демо-превью')
  document.title = 'Mentalix — демо-превью'
}

const showcaseRequested =
  import.meta.env.DEV &&
  new URLSearchParams(window.location.search).get('showcase') === 'archetypes'

const uiLabEnabled =
  import.meta.env.DEV ||
  import.meta.env.VERCEL_ENV === 'preview' ||
  isUiLabHostAllowed(window.location.hostname)

const dialogPreviewEnabled =
  import.meta.env.DEV ||
  import.meta.env.VERCEL_ENV === 'preview' ||
  window.location.hostname === 'mentalix-preview.vercel.app'

const dialogPreviewRequested =
  dialogPreviewEnabled && new URLSearchParams(window.location.search).get('dialog_preview') === '1'

const uiLabParam = new URLSearchParams(window.location.search).get('ui_lab')

// UI Lab доступен только в dev/Vercel Preview. Старые значения query
// сохраняются как совместимые алиасы в новом маршруте UiLab.
const uiLabRequested = uiLabEnabled && uiLabParam !== null

const uiLabSection =
  uiLabParam === '1' ? 'experiments' : uiLabParam === 'showcase' ? 'baseline' : uiLabParam

const UiLab = uiLabEnabled ? lazy(() => import('./components/ui-lab/UiLab')) : null

const PersonaPicker = dialogPreviewEnabled
  ? lazy(() => import('./screens/mentalix/PersonaPicker'))
  : null

const motionKitEnabled = import.meta.env.DEV || import.meta.env.VERCEL_ENV === 'preview'

const motionKitRequested =
  motionKitEnabled && new URLSearchParams(window.location.search).get('motion_kit') === '1'

const cardLabEnabled = import.meta.env.DEV || import.meta.env.VERCEL_ENV === 'preview'

const cardLabRequested =
  cardLabEnabled && new URLSearchParams(window.location.search).get('card_lab') === '1'

const onboardingPreviewRequested =
  import.meta.env.DEV &&
  new URLSearchParams(window.location.search).get('onboarding_preview') === '1'

const ArchetypeShowcase = import.meta.env.DEV
  ? lazy(() => import('./components/archetype-art/ArchetypeShowcase'))
  : null

const PracticeMotionKit = motionKitEnabled
  ? lazy(() => import('./components/ui-lab/PracticeMotionKit'))
  : null

const CardDirectionsLab = cardLabEnabled
  ? lazy(() => import('./components/ui-lab/CardDirectionsLab'))
  : null

const OnboardingPreview = import.meta.env.DEV ? lazy(() => import('./screens/Onboarding')) : null

function RootScreen() {
  if (dialogPreviewRequested && PersonaPicker) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <PersonaPicker user={null} onPick={() => undefined} />
      </Suspense>
    )
  }

  if (cardLabRequested && CardDirectionsLab) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <CardDirectionsLab />
      </Suspense>
    )
  }

  if (motionKitRequested && PracticeMotionKit) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <PracticeMotionKit />
      </Suspense>
    )
  }

  if (onboardingPreviewRequested && OnboardingPreview) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <OnboardingPreview user={null} onFinish={() => window.location.reload()} />
      </Suspense>
    )
  }

  if (uiLabRequested && UiLab) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <UiLab initialSection={uiLabSection} />
      </Suspense>
    )
  }

  if (showcaseRequested && ArchetypeShowcase) {
    return (
      <Suspense fallback={<div className="min-h-[100dvh] bg-emerald-deep" />}>
        <ArchetypeShowcase />
      </Suspense>
    )
  }

  return <App />
}

// Ловушка ошибок: вместо чёрного экрана показываем текст ошибки,
// чтобы её можно было сфотографировать и починить
class ErrorBoundary extends Component {
  constructor(props) {
    super(props)
    this.state = { error: null }
  }
  static getDerivedStateFromError(error) {
    return { error }
  }
  render() {
    if (this.state.error) {
      return (
        <div
          style={{
            padding: 24,
            color: 'rgb(var(--c-text))',
            background: 'rgb(var(--c-bg))',
            minHeight: '100vh',
            fontFamily: 'monospace',
            fontSize: 13,
          }}
        >
          <p style={{ fontWeight: 700, marginBottom: 12 }}>
            Ошибка приложения — покажи этот экран разработчику:
          </p>
          {this.state.error && this.state.error.message && (
            <p
              style={{
                color: 'rgb(var(--c-gold))',
                fontWeight: 600,
                marginBottom: 12,
                whiteSpace: 'pre-wrap',
              }}
            >
              {this.state.error.message}
            </p>
          )}
          <pre style={{ whiteSpace: 'pre-wrap', color: 'rgb(var(--c-muted))', fontSize: 11 }}>
            {String(
              this.state.error &&
                (this.state.error.stack || this.state.error.message || this.state.error)
            )}
          </pre>
        </div>
      )
    }
    return this.props.children
  }
}

window.addEventListener('error', e => {
  const root = document.getElementById('root')
  if (root && !root.hasChildNodes()) {
    root.innerHTML =
      '<pre style="padding:24px;color:#D9D9D9;background:#0A0A0A;min-height:100vh;white-space:pre-wrap;font-size:13px">Ошибка загрузки — покажи разработчику:\n\n' +
      (e.message || e.error) +
      '</pre>'
  }
})

// tgShell — dev-only Telegram iOS simulation. Dynamically imported so the
// code never ships in the production bundle. ?tgshell=0 is handled inside.
// navigator.webdriver excludes Playwright/automated browsers (CI UX tests).
async function startApp() {
  if (
    (import.meta.env.DEV || import.meta.env.VITE_TG_SHELL === '1') &&
    import.meta.env.VITE_TG_SHELL !== '0' &&
    !navigator.webdriver
  ) {
    const { initTgShell } = await import('./tgShell')
    initTgShell()
  }

  createRoot(document.getElementById('root')).render(
    <StrictMode>
      <ErrorBoundary>
        <AppProviders>
          <RootScreen />
        </AppProviders>
      </ErrorBoundary>
    </StrictMode>
  )
}

startApp()
